/* Body interpretation and explainable, reviewable coaching drafts. */
let bodyReportId='',coachDraftCache=null;
function bodyRecords(){return data.measurements.filter(m=>!m.reviewRequired&&m.date<=today()).sort((a,b)=>(b.measuredAt||b.date).localeCompare(a.measuredAt||a.date))}
function currentBodyReport(){const rows=bodyRecords();return rows.find(m=>m.id===bodyReportId)||rows[0]}
function reportDevice(m){return m.device||(m.source?.includes('2026-09-18')?'ميزان منزلي':'إدخال يدوي')}
function coachInputs(m){const saved=data.nutrition.coachPreferences||{},n=data.nutrition.intake||{},owner=window.fitnessAccount?.owner&&activeProfile==='default';const sex=saved.sex||n.sex||m.sex||(owner?'ذكر':''),age=saved.age||(owner?new Date().getFullYear()-1984:n.age||null),height=saved.height||n.height||m.height||(owner?175:null);const bmi=height?m.weight/(height/100)**2:null;const suggested=m.bfr!=null&&bmi>=25&&m.bfr>(sex==='أنثى'?28:20)?'تنشيف':'إعادة تركيب الجسم';return {...saved,sex,age,height,date:m.date,weight:m.weight,bfr:m.bfr??null,muscleWeight:m.muscleWeight??null,bmr:m.bmr||null,goal:saved.goal||n.goal||suggested,suggested,activity:saved.activity||n.activity||'نشاط متوسط',excluded:n.excluded||[],otherAllergy:n.otherAllergy||'',medical:!!n.medical||!!saved.medical,days:saved.days||'3',level:saved.level||'مبتدئ / عائد',equipment:saved.equipment||'النادي والأجهزة',focus:saved.focus||'توازن الجسم',healthConfirmed:saved.healthConfirmed===true,injury:!!saved.injury};}
function coachWorkout(n){
 if(data.training?.weeklySplitActive)return structuredClone(data.training.exercises||[]);
 const machine=n.equipment==='النادي والأجهزة';
 const library={squat:[machine?'Leg Press':'Goblet Squat','رجل','8–12',machine?'Goblet Squat':'Bodyweight Squat'],hinge:['Dumbbell Romanian Deadlift','رجل','8–12','Hip Hinge بوزن الجسم'],chest:[machine?'Chest Press':'Dumbbell Bench Press','صدر','8–12','Incline Push-up'],row:[machine?'Seated Cable Row':'One-arm Dumbbell Row','ظهر','8–12','Resistance Band Row'],pull:[machine?'Lat Pulldown':'Band Pulldown','ظهر','8–12','Assisted Pull-up'],shoulder:[machine?'Shoulder Press':'Dumbbell Shoulder Press','كتف','8–12','Landmine Press'],lateral:['Dumbbell Lateral Raise','كتف','12–15','Cable Lateral Raise'],curl:['Dumbbell Curl','باي','10–15','Cable Curl'],triceps:[machine?'Triceps Pushdown':'Dumbbell Triceps Extension','تراي','10–15','Close-grip Incline Push-up'],hip:['Hip Thrust','رجل','10–12','Glute Bridge'],legcurl:[machine?'Leg Curl':'Sliding Leg Curl','رجل','10–15','Stability Ball Leg Curl'],calf:['Calf Raise','رجل','12–15','Seated Calf Raise'],core:['Dead Bug','بطن','8–12 / جهة','Bird Dog'],lunge:['Reverse Lunge','رجل','8–12 / رجل','Step Up']};
 let days=n.days==='4'?[['chest','row','pull','shoulder','curl','triceps'],['squat','hinge','legcurl','hip','calf','core'],['chest','row','pull','lateral','curl','triceps'],['squat','lunge','legcurl','hip','calf','core']]:[['squat','chest','row','hinge','lateral','core'],['lunge','pull','shoulder','hip','curl','core'],['squat','chest','row','legcurl','triceps','calf']].slice(0,Number(n.days));
 if(n.focus==='الصدر والجزء العلوي'&&n.days!=='4')days[1][2]='chest';
 if(n.focus==='الأرداف والجزء السفلي'&&n.days!=='4')days[0][4]='hip';
 const sets=3;return days.flatMap((keys,d)=>keys.map((key,i)=>{const [exercise,group,range,alternative]=library[key];const reps=n.level==='مبتدئ / عائد'&&range==='8–12'?'10–12':range;return {id:'coach-'+(d+1)+'-'+key+'-'+i,session:String(d+1),exercise,group,reps,sets,weight:'',alternative,notes:'اترك نحو 2–3 عدات ممكنة؛ حركة متحكم بها دون ألم. راحة '+(['lateral','curl','triceps','calf','core'].includes(key)?'60–90 ثانية':'90–120 ثانية')+'. الجولة الرابعة اختيارية في السجل.'}}));
}
function coachDraft(m){const n=coachInputs(m),key=JSON.stringify([m,n,selected,data.training?.exercises]);if(coachDraftCache?.key===key)return coachDraftCache.value;let plan=null,error='';
 try{if(m.fatMass!=null&&m.bfr!=null&&Math.abs(m.fatMass/m.weight*100-m.bfr)>3)throw Error('كتلة الدهون ونسبتها غير متسقتين؛ راجع القياس قبل إنشاء الخطة.');if(!n.age||!n.height||!['ذكر','أنثى'].includes(n.sex))throw Error('أكد العمر والطول والجنس مرة واحدة لإكمال الخطة.');if(n.medical||n.injury)throw Error('تحتاج الخطة إلى تخصيص من مختص بسبب الحالة الصحية أو الإصابة؛ تظل قراءة القياسات متاحة.');if(n.goal==='تنشيف'&&n.bfr!=null&&n.bfr<(n.sex==='ذكر'?10:18))throw Error('لن يُقترح خفض إضافي للسعرات مع هذه النسبة المنخفضة. راجع القياس والهدف مع مختص.');plan=buildPlan(n);}catch(e){error=e.message.replace('تم حفظ البيانات. ','').replace('تم حفظ القياسات. ','')}
 const value={n,plan,error,workout:plan?coachWorkout(n):[]};coachDraftCache={key,value};return value;
}
function bodyMetric(label,value,unit,detail){return `<div class="body-metric"><small>${label}</small><strong>${value==null?'—':fmt(value)} <span>${unit}</span></strong><p>${detail}</p></div>`}
function reportTrend(m){const rows=bodyRecords().filter(r=>reportDevice(r)===reportDevice(m)&&(r.measuredAt||r.date)<=(m.measuredAt||m.date)).slice(0,8).reverse();if(rows.length<2)return '<p class="sub">لا توجد قراءة أقدم من نفس المصدر للمقارنة.</p>';const prev=rows.at(-2),metrics=[['الوزن','weight','كجم'],['نسبة الدهون','bfr','نقطة مئوية'],[m.totalMuscleMass!=null?'عضلات Boditrax':'عضلات هيكلية',m.totalMuscleMass!=null?'totalMuscleMass':'muscleWeight','كجم']];return `<p class="sub">مقارنة من المصدر نفسه مع ${pretty(prev.date)}.</p><div class="body-metrics">${metrics.filter(([,k])=>m[k]!=null&&prev[k]!=null).map(([l,k,u])=>bodyMetric(l,m[k]-prev[k],u,`${fmt(prev[k])} ← ${fmt(m[k])}`)).join('')}</div><div class="body-trend" aria-label="آخر أوزان من المصدر نفسه">${rows.map(r=>`<div><span style="height:${Math.max(8,Math.min(90,(r.weight-Math.min(...rows.map(x=>x.weight))+1)/(Math.max(...rows.map(x=>x.weight))-Math.min(...rows.map(x=>x.weight))+1)*90))}px"></span><b>${fmt(r.weight)}</b><small>${esc(r.date.slice(5))}</small></div>`).join('')}</div><p class="sub">ارتفاع الأعمدة يوضح التغير النسبي في الوزن؛ راجع القيم المكتوبة بالكيلوجرام. اختلاف الماء وظروف الفحص قد يؤثر في المقارنة.</p>`}
function segmentPanel(m){if(!m.segments?.length){const detailed=bodyRecords().find(r=>r.segments?.length);return `<div class="card"><h2>توزيع الجسم</h2><p>هذا القياس لا يتضمن تفاصيل الذراعين والساقين والجذع.</p>${detailed?`<button class="button secondary" data-body-select="${esc(detailed.id)}">عرض تفاصيل ${esc(reportDevice(detailed))} · ${pretty(detailed.date)}</button>`:''}</div>`}return `<div class="card"><h2>توزيع الجسم حسب المناطق</h2><p class="sub">${m.muscleType==='total'?'كتلة عضلات Boditrax':'الكتلة الخالية من الدهون القطاعية'} — ${pretty(m.date)}. الأرقام لا تثبت ضعفًا عضليًا أو تشخّص إصابة.</p><div class="table-wrap"><table><thead><tr><th>المنطقة</th><th>${m.muscleType==='total'?'عضلات':'كتلة خالية من الدهون'} كجم</th><th>دهون كجم</th></tr></thead><tbody>${m.segments.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.lean==null?'—':fmt(s.lean)}</td><td>${s.fat==null?'—':fmt(s.fat)}</td></tr>`).join('')}</tbody></table></div><p class="notice">تدريب الجسم المتوازن هو الأساس. استخدم التمارين الأحادية لملاحظة جودة الحركة بين الجانبين، ولا تضف حملًا لجانب معين اعتمادًا على فرق الفحص وحده. لا نَعِد بإزالة الدهون من منطقة بعينها.</p></div>`}
function coachMeals(plan){return `<div class="coach-days">${plan.days.map((d,i)=>`<details ${i===0?'open':''}><summary>${pretty(d.date,{weekday:'long',day:'numeric',month:'long'})} · ${fmt(d.calories)} سعرة · ${fmt(d.protein)} غ بروتين</summary>${d.meals.map(m=>`<div class="coach-meal"><b>${esc(m.name)} · ${m.time}</b><p>${m.items.map(x=>`${esc(foods[x.key][0])} <strong>${x.g} غ</strong>`).join(' + ')}</p><small>${fmt(m.calories)} سعرة · بروتين ${fmt(m.protein)} · كارب ${fmt(m.carbs)} · دهون ${fmt(m.fat)} غ</small></div>`).join('')}</details>`).join('')}</div>`}
function coachTraining(rows,n){if(data.training?.weeklySplitActive)return `<p class="notice">ستُحفظ خطتك الأسبوعية الحالية وتعديلاتك: الأحد صدر، الجمعة راحة والسبت كارديو اختياري.</p>${trainingDays.map(([s,label])=>`<details class="coach-session"><summary>${label} · ${esc(weeklyDayDetail(s))}</summary>${rows.filter(r=>r.session===s).map(r=>`<p>${esc(r.exercise)} · ${r.sets} × ${esc(r.reps)}</p>`).join('')}</details>`).join('')}`;return `<p class="notice">${n.days} أيام · ${n.days==='4'?'علوي / سفلي':'كامل الجسم'} · نحو 45–60 دقيقة للجلسة. اترك يومًا بين جلسات كامل الجسم، أو وزّع ٤ أيام: علوي، سفلي، راحة، علوي، سفلي. الجنس يُستخدم في حساب الطاقة؛ اختيار الحركات يعتمد على الخبرة والهدف والأدوات.</p>${[...new Set(rows.map(r=>r.session))].map(s=>`<details class="coach-session" ${s==='1'?'open':''}><summary>الجلسة ${s} · ${rows.filter(r=>r.session===s).length} تمارين</summary>${rows.filter(r=>r.session===s).map(r=>`<div class="coach-meal"><strong>${esc(r.exercise)}</strong><p>${r.sets} جولات × ${esc(r.reps)} · ${esc(r.group)}</p><small>بديل: ${esc(r.alternative)} · ${esc(r.notes)}</small></div>`).join('')}</details>`).join('')}<p class="sub">ابدأ بـ5–8 دقائق إحماء وجولات خفيفة للحركات الرئيسية. للمبتدئ يمكن الاكتفاء بجولتين أول أسبوع ثم ثلاث مع تحسن التحمل. زد الحمل بأصغر خطوة متاحة فقط بعد بلوغ أعلى العدات بحركة سليمة وبقاء عدات ممكنة في جلستين؛ لا توجد زيادة تلقائية للأوزان.</p>`}
function renderBodyCoach(){const m=currentBodyReport();if(!m)return `<div class="card"><h2>تحليل جسمك وخطتك</h2><p>أضف أول قياس أو اقرأ تقرير InBody لإعداد مسودة الأكل والتمرين.</p>${fb('قراءة تقرير / إضافة قياسات','intake')}</div>`;const {n,plan,error,workout}=coachDraft(m),ageDays=Math.floor((Date.parse(today())-Date.parse(m.date))/86400000),fat=m.fatMass??(m.bfr!=null?m.weight*m.bfr/100:null),lean=m.leanWeight??(fat!=null?m.weight-fat:null);return `<div id="body-report"><section class="body-hero"><div><p class="eyebrow">تحليل الجسم • خطة قابلة للتطبيق</p><h2>${esc(n.goal)} مع متابعة العضلات والأداء</h2><p>${esc(reportDevice(m))} · ${pretty(m.date)} · ${esc(profileName())}</p></div><div class="quick-buttons"><button class="button" data-coach="setup">تخصيص خطتي</button><button class="button secondary" data-coach="print">طباعة التقرير / PDF</button></div></section><div class="card no-print"><label class="field">القياس المعروض<select id="bodyReportSelect">${bodyRecords().map(r=>`<option value="${esc(r.id)}" ${r.id===m.id?'selected':''}>${esc(r.date)} · ${esc(reportDevice(r))} · ${fmt(r.weight)} كجم</option>`).join('')}</select></label><p class="sub">الخطة أدناه مبنية على القياس المعروض. لا نخلط عضلات Boditrax وSMM في InBody أو نسبة العضلات في الميزان.</p>${ageDays>90?`<p class="notice">هذا القياس عمره ${ageDays} يومًا؛ الخطة للمراجعة التاريخية. يلزم تأكيد الوزن الحالي قبل اعتمادها.</p>`:''}</div><div class="body-metrics">${bodyMetric('الوزن',m.weight,'كجم','وزن الجسم بالكامل')}${bodyMetric('دهون الجسم',m.bfr,'% ',m.bfrCalculated?'محسوبة من كتلة الدهون ÷ الوزن':'تقدير الجهاز، يتأثر بظروف الفحص')}${bodyMetric(m.totalMuscleMass!=null?'إجمالي العضلات':m.muscleWeight!=null?'العضلات الهيكلية SMM':'نسبة العضلات',m.totalMuscleMass??m.muscleWeight??m.musclePercent,m.totalMuscleMass!=null||m.muscleWeight!=null?'كجم':'%',m.totalMuscleMass!=null?'Boditrax — ليست SMM':m.muscleWeight!=null?'عضلات مرتبطة بالهيكل العظمي':'لا تُحوّل مباشرة إلى SMM')}${bodyMetric('طاقة الراحة BMR',m.bmr,'سعرة',m.bmrKJ?'تحويل kJ إلى kcal بالقسمة على 4.184':'ليست سعرات اليوم الكامل')}</div><div class="grid-two"><div class="card"><h2>ممّ يتكون وزنك؟</h2>${fat!=null&&lean!=null?`<div class="composition-bar" role="img" aria-label="دهون ${fmt(fat)} كجم، كتلة خالية من الدهون ${fmt(lean)} كجم"><span style="width:${Math.min(100,fat/m.weight*100)}%"></span></div><div class="goal-row"><span>دهون</span><b>${fmt(fat)} كجم</b></div><div class="goal-row"><span>كتلة خالية من الدهون</span><b>${fmt(lean)} كجم</b></div><p class="sub">الكتلة الخالية من الدهون تشمل الماء والعظام والعضلات؛ الماء ليس جزءًا إضافيًا يُجمع فوقها.</p>`:'<p>أضف نسبة أو كتلة الدهون لإظهار التقسيم.</p>'}<p class="sub">BMI: ${m.bmi!=null?fmt(m.bmi):n.height?fmt(m.weight/(n.height/100)**2):'—'} · دهون حشوية: ${m.visceralFat??'—'} حسب مقياس الجهاز. لا نستخدم BMI وحده لتحديد هدف الشكل.</p></div><div class="card"><h2>ما الذي تغير؟</h2>${reportTrend(m)}</div></div>${segmentPanel(m)}<div class="card"><h2>لماذا هذه الخطة؟</h2><p>${n.goal==='تنشيف'?'خفض معتدل للطاقة مع مقاومة منتظمة وبروتين موزع على اليوم، بهدف تقليل الدهون والمحافظة على الأداء.':n.goal==='تضخيم'?'زيادة صغيرة للطاقة مع تقدم تدريجي في التدريب؛ راقب محيط الخصر والوزن لتقييم الزيادة.':n.goal==='إعادة تركيب الجسم'?'طاقة قريبة من الثبات مع خفض بسيط، ومقاومة منتظمة؛ قيّم الشكل والقوة بجانب متوسط الوزن.':'طاقة تقديرية للثبات، ومقاومة متوازنة ونشاط منتظم.'}</p><p class="sub">الهدف المبدئي المقترح: ${esc(n.suggested)}. اقتراح تنظيمي يعتمد على نسبة الدهون والوزن بالنسبة للطول، وليس تشخيصًا أو نسبة دهون مثالية إلزامية. تستطيع تغييره. النشاط ${esc(n.activity)} والخبرة ${esc(n.level)} ${n.healthConfirmed?'مؤكدان من إعداداتك':'افتراضان يحتاجان مراجعتك مرة واحدة'}.</p></div><div class="card no-print"><h2>خطة التغذية</h2><p>راجع وجباتك وكمياتها وعدّل مكوناتها من قسم التغذية.</p><a class="button" href="#nutrition">فتح خطة التغذية</a></div><div class="card"><h2>كيف أتمرن لتحسين الشكل؟</h2>${plan?coachTraining(workout,n):'<p>تظهر الخطة بعد استكمال المعلومات الأساسية والتأكد من ملاءمتها لحالتك.</p>'}</div><div class="card"><h2>المراجعة بعد أسبوعين</h2><ol><li>سجّل الوزن في ظروف متشابهة، وقارن متوسط أسبوعين بدل قراءة منفردة.</li><li>تابع محيط الخصر أسبوعيًا، وعدات وأوزان التمارين، والطاقة والتعافي.</li><li>إذا خالف الاتجاه هدفك مع اكتمال التسجيل، راجع الكميات والنشاط أولًا ثم عدّل الخطة؛ لا نغير السعرات تلقائيًا.</li></ol><p class="sub">امشِ بوتيرة مريحة في أيام الراحة حسب تحملك، وأضف المدة تدريجيًا. الألم أو الدوخة أو ضيق النفس غير المعتاد يستدعي إيقاف التمرين والتقييم المناسب.</p></div><div class="card no-print"><div class="quick-buttons"><button class="button" data-coach="apply" ${!plan?'disabled':''}>اعتماد التغذية وبرنامج التمارين</button><button class="button secondary" data-coach="setup">تعديل الاختيارات</button></div><p class="sub">الاعتماد يستبدل الخطة المقترحة فقط ويضبط أهداف السعرات والماكروز؛ لا يضيف وجبات مأكولة أو تمارين منجزة. راجع الحساسية والحالة الصحية قبل الاعتماد.</p></div><details class="card"><summary>المراجع وحدود التفسير</summary><p>القياسات تقديرية وليست تشخيصًا. تختلف نتائج الأجهزة وتعريفات العضلات، لذا تُقارن الاتجاهات داخل المصدر نفسه. الخطة الغذائية المرفقة مرجع لأفكار الأطعمة فقط؛ لم تُعتمد جرعات مكملاتها أو منع مجموعات غذائية تلقائيًا.</p><div class="quick-buttons"><a href="https://inbodyusa.com/blogs/inbodyblog/41937409-we-tested-402-people-at-thefitexpo-heres-what-we-found/" target="_blank" rel="noopener">اختلاف مراجع نسبة الدهون</a><a href="https://qr.inbody.com/ri/770/adult/en" target="_blank" rel="noopener">تفسير InBody</a><a href="https://boditrax.zendesk.com/hc/en-gb/articles/360000373845-Muscle-Mass" target="_blank" rel="noopener">تعريف عضلات Boditrax</a><a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">تدريب المقاومة ACSM</a><a href="https://link.springer.com/article/10.1186/s12970-017-0177-8" target="_blank" rel="noopener">البروتين ISSN</a></div></details></div>`}
const coachDialog=document.createElement('dialog');coachDialog.id='coachDialog';coachDialog.setAttribute('aria-label','تخصيص الخطة');document.body.append(coachDialog);
function openCoachSetup(){const m=currentBodyReport();if(!m){openFeature('intake');return}const n=coachInputs(m);coachDialog.innerHTML=`<form id="coachSetupForm"><div class="dialog-head"><h2>تخصيص مرة واحدة، والخطة جاهزة</h2><button type="button" class="icon-button" data-coach="close">×</button></div><div class="form-grid">${select('sex','الجنس',['ذكر','أنثى'],n.sex)}${number('age','العمر الحالي',n.age||'',true,18,1,65)}${number('height','الطول سم',n.height||'',true,100,.1,230)}${select('goal','الهدف',['تنشيف','تضخيم','إعادة تركيب الجسم','ثبات الوزن','لياقة وصحة عامة'],n.goal)}${select('activity','نشاطك اليومي',['قليل الحركة','نشاط خفيف','نشاط متوسط','نشاط مرتفع'],n.activity)}${select('days','أيام المقاومة أسبوعيًا',['2','3','4'],n.days)}${select('level','الخبرة',['مبتدئ / عائد','منتظم أكثر من 6 أشهر'],n.level)}${select('equipment','الأدوات',['النادي والأجهزة','أوزان حرة وأشرطة مقاومة'],n.equipment)}${select('focus','الأولوية الشكلية',['توازن الجسم','الصدر والجزء العلوي','الأرداف والجزء السفلي'],n.focus)}<p class="field full sub">الوزن ${fmt(m.weight)} كجم من ${pretty(m.date)}. اختر قياسًا آخر من لوحة الجسم لتغيير مصدر الخطة.</p><p class="sets-title">الحساسية والاستبعادات</p>${[['dairy','حليب ومشتقاته'],['egg','بيض'],['fish','سمك'],['nuts','مكسرات'],['gluten','قمح / جلوتين'],['soy','صويا']].map(([k,l])=>checks('exclude_'+k,l,n.excluded.includes(k))).join('')}${input('otherAllergy','حساسيات أخرى',n.otherAllergy)}${checks('medical','لدي مرض مزمن أو أدوية تؤثر على التغذية، أو حمل/رضاعة أو اضطراب أكل',n.medical)}${checks('injury','لدي إصابة أو ألم يؤثر على التمرين',n.injury)}<label class="check-label field full"><input name="confirmed" type="checkbox" required ${n.healthConfirmed?'checked':''}> راجعت المعلومات الصحية والحساسيات والأهداف أعلاه.</label></div><p class="danger" id="coachSetupError" role="alert"></p><div class="dialog-actions"><button class="button">إنشاء خطتي تلقائيًا</button></div></form>`;coachDialog.showModal();$('#coachSetupForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const next=structuredClone(data);next.nutrition.coachPreferences={age:Number(f.age),height:Number(f.height),sex:f.sex,goal:f.goal,activity:f.activity,days:f.days,level:f.level,equipment:f.equipment,focus:f.focus,healthConfirmed:f.confirmed==='on',medical:f.medical==='on',injury:f.injury==='on'};next.nutrition.intake={...(next.nutrition.intake||{}),excluded:['dairy','egg','fish','nuts','gluten','soy'].filter(k=>f['exclude_'+k]==='on'),otherAllergy:f.otherAllergy.trim(),medical:f.medical==='on'};try{validate(next);if(commit(next,'تم تجهيز مسودة خطتك'))coachDialog.close()}catch(err){$('#coachSetupError').textContent=err.message}}}
function applyCoachPlan(){const m=currentBodyReport(),draft=coachDraft(m);if(!draft.plan)return;if(!draft.n.healthConfirmed){openCoachSetup();return}if(Date.parse(today())-Date.parse(m.date)>90*86400000){notify('القياس قديم. اختر قياسك الأحدث أو سجّل قياسًا حاليًا قبل اعتماد الخطة.',true);return}if((data.training.exercises?.length||data.nutrition.plan)&&!confirm('اعتماد هذه المسودة بدل خطتي التغذية والتمرين الحاليتين؟ ستبقى جميع سجلات الأداء والوجبات السابقة.'))return;const next=structuredClone(data);next.nutrition={...next.nutrition,intake:draft.n,plan:draft.plan,blockReason:'',coachReportId:m.id};next.training.exercises=data.training.weeklySplitActive?structuredClone(draft.workout):draft.workout.map(x=>({...x,id:uid()}));Object.assign(next.targets,draft.plan.targets);next.targets.workoutDays=data.training.weeklySplitActive?5:Number(draft.n.days);try{validate(next);commit(next,'تم اعتماد خطة التغذية والتمارين؛ ابدأ من قسم التغذية أو التمارين.')}catch(e){notify(e.message,true)}}
document.addEventListener('change',e=>{if(e.target.id==='bodyReportSelect'){bodyReportId=e.target.value;render()}});
document.addEventListener('click',e=>{const ref=e.target.closest('[data-body-select]');if(ref){bodyReportId=ref.dataset.bodySelect;view='body';location.hash='body';render()}const action=e.target.closest('[data-coach]')?.dataset.coach;if(action==='setup')openCoachSetup();if(action==='close')coachDialog.close();if(action==='apply')applyCoachPlan();if(action==='print'){document.querySelectorAll('#body-report details').forEach(d=>{d.dataset.wasOpen=d.open?'1':'0';d.open=true});document.body.classList.add('printing-body');window.print()}});
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-body');document.querySelectorAll('#body-report details').forEach(d=>{d.open=d.dataset.wasOpen==='1'})});
const beforeBodyToday=renderToday;renderToday=()=>`<section class="body-hero"><div><p class="eyebrow">من القياس إلى التطبيق</p><h2>تحليل جسمك وخطتك المقترحة</h2><p>قراءة الدهون والعضلات، وجبات بالأوزان، وبرنامج مقاومة مناسب لاختياراتك.</p></div><a class="button" href="#body">افتح لوحة جسمك</a></section>`+beforeBodyToday();
render();
